import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.Ch4PdLd_.js";const c=JSON.parse('{"title":"在 tmux 中运行","description":"","frontmatter":{},"headers":[],"relativePath":"platform/tmux.md","filePath":"platform/tmux.md"}'),n={name:"platform/tmux.md"};function l(h,s,p,d,o,k){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="在-tmux-中运行" tabindex="-1">在 tmux 中运行 <a class="header-anchor" href="#在-tmux-中运行" aria-label="Permalink to &quot;在 tmux 中运行&quot;">​</a></h1><p>nek 可以在 tmux 里运行，但 tmux 可能把 <code>Shift+Enter</code>、<code>Ctrl+Enter</code> 和普通 <code>Enter</code> 报告成同一个键。开启扩展按键后，nek 才能区分它们。</p><h2 id="查看-tmux-版本" tabindex="-1">查看 tmux 版本 <a class="header-anchor" href="#查看-tmux-版本" aria-label="Permalink to &quot;查看 tmux 版本&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tmux</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -V</span></span></code></pre></div><p>tmux 3.5 及更新版本用下面推荐的 CSI-u 配置；3.2 到 3.4 用 <a href="#old">旧版本配置</a>。</p><h2 id="tmux-3-5-开启扩展按键" tabindex="-1">tmux 3.5+：开启扩展按键 <a class="header-anchor" href="#tmux-3-5-开启扩展按键" aria-label="Permalink to &quot;tmux 3.5+：开启扩展按键&quot;">​</a></h2><p>在 <code>~/.tmux.conf</code> 中加入：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extended-keys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> on</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extended-keys-format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> csi-u</span></span></code></pre></div><p>终端本身不直接提供 Kitty 键盘协议时，nek 会请求扩展按键上报。CSI-u 是通过 tmux 转发修饰键最可靠的格式。</p><h2 id="重启-tmux" tabindex="-1">重启 tmux <a class="header-anchor" href="#重启-tmux" aria-label="Permalink to &quot;重启 tmux&quot;">​</a></h2><p>配置作用于 tmux 服务器。为确保生效，关闭所有 tmux 会话后启动新的服务器。</p><p>如果用命令行停止服务器，请先保存工作，下面的命令会结束这个服务器管理的<strong>所有</strong>会话：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tmux</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kill-server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tmux</span></span></code></pre></div><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>在新的 tmux 会话里启动 nek，确认：</p><ol><li><code>Shift+Enter</code> 在输入框里换行；</li><li><code>Enter</code> 发送；</li><li><code>Alt+Enter</code> 排队追加消息（macOS 和 Linux）。Windows 和 WSL 默认用 <code>Ctrl+Q</code>。</li></ol><p>如果这些键仍然和普通 <code>Enter</code> 一样，检查 tmux 外层的终端能否上报修饰键，见 <a href="/nekcode/platform/terminal-setup">终端设置</a>。</p><h2 id="old" tabindex="-1">tmux 3.2 到 3.4 <a class="header-anchor" href="#old" aria-label="Permalink to &quot;tmux 3.2 到 3.4 {#old}&quot;">​</a></h2><p>这些版本支持扩展按键，但不支持 <code>extended-keys-format csi-u</code>。只加：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extended-keys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> on</span></span></code></pre></div><p>nek 支持这些版本使用的 xterm <code>modifyOtherKeys</code> 格式。重启 tmux 后重复上面的验证。</p><p>更旧的版本请升级 tmux，或在 tmux 外运行 nek，不要依赖带修饰键的回车。</p><h2 id="全屏模式下滚动" tabindex="-1">全屏模式下滚动 <a class="header-anchor" href="#全屏模式下滚动" aria-label="Permalink to &quot;全屏模式下滚动&quot;">​</a></h2><p>nek 默认以全屏模式启动，在备用屏幕上自己绘制对话，所以 tmux 的回滚（copy mode）里看不到对话内容。</p><ul><li><strong>键盘始终可用</strong>：<code>PageUp</code>/<code>PageDown</code> 翻页，<code>Home</code> 跳到开头，<code>End</code> 回到末尾并跟随新输出。这些按键可在 <a href="/nekcode/reference/keybindings">快捷键</a> 中以 <code>tui.altScreen.*</code> 修改。</li><li><strong>鼠标滚轮</strong>只有在 tmux 转发鼠标事件时才能到达 nek。在 <code>~/.tmux.conf</code> 中加入下面一行，然后运行 <code>tmux source-file ~/.tmux.conf</code> 或重启 tmux：</li></ul><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mouse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> on</span></span></code></pre></div><p>没有 <code>set -g mouse on</code> 时，tmux 自己处理滚轮，nek 的对话不会滚动。</p><h2 id="改回普通模式" tabindex="-1">改回普通模式 <a class="header-anchor" href="#改回普通模式" aria-label="Permalink to &quot;改回普通模式&quot;">​</a></h2><p>普通模式把对话直接输出到终端，tmux 的 copy mode 和回滚照常可用。只用一次：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tui-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> regular</span></span></code></pre></div><p>设为默认：在 <code>/settings</code> 中选择，或在 <code>~/.nek/agent/settings.json</code> 中设置 <code>&quot;tuiMode&quot;: &quot;regular&quot;</code>。</p><h2 id="推荐的完整配置" tabindex="-1">推荐的完整配置 <a class="header-anchor" href="#推荐的完整配置" aria-label="Permalink to &quot;推荐的完整配置&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ~/.tmux.conf</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extended-keys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> on</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extended-keys-format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> csi-u</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # tmux 3.5+</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mouse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> on</span></span></code></pre></div>`,33)])])}const u=a(n,[["render",l]]);export{c as __pageData,u as default};
